// Investment overview: envelope tiles (first 3) + portfolio rows (first 5). Runs on records/masters onDataQuerySuccess and the overview page's onPageLoad
const e = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const money = n => '$' + Number(n || 0).toLocaleString('en-US', {maximumFractionDigits: 0});
const all = queries.records.data || [], envelopes = queries.masters.data || [];
const sum = (p, k) => (p.items || []).reduce((s, i) => s + Number(i[k] || 0), 0);
const committed = p => ['Approved', 'Active', 'Completed'].includes(p.status);
const used = name => all.filter(p => p.context === name && committed(p)).reduce((s, p) => s + sum(p, 'estimate'), 0);
return {
  envelopes: envelopes.slice(0, 3).map(v => {
    const u = used(v.name), cap = Number(v.capacity || 0);
    return { name: String(v.name || '').toUpperCase(), remaining: money(cap - u), sub: 'unallocated of ' + money(cap), pct: cap ? Math.min(100, u / cap * 100) : 0 };
  }),
  rows: all.slice(0, 5).map(p => ({ name: e(p.name), owner: e(p.owner), status: p.status, proposed: money(sum(p, 'estimate')), committed: money(sum(p, 'commit')), actual: money(sum(p, 'actual')) }))
};

// Selected proposal for the Business case & spend page: runs on records.onDataQuerySuccess and the page's onPageLoad
const e = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const p = (queries.records.data || []).find(r => r.id === variables.recordId);
const history = (p?.history || []).slice().reverse().map(h => ({ event: e(h.event), at: e(String(h.at || '').slice(0, 16).replace('T', ' ')), note: h.note || '' }));
return {
  has: !!p,
  envelope: p?.context || 'No record selected',
  status: p?.status || 'Choose a record',
  ownerDue: p ? (p.owner || '') + ' · ' + (p.due || '') : '',
  scopeHead: 'SCOPE & CURRENT EVIDENCE · REVISION ' + (p?.revision || '—'),
  scope: p?.scope || 'Open a record from the register to see its context and next decisions.',
  history: history.length ? history : [{ event: '', at: 'Select a record to inspect its saved activity.', note: '' }]
};
